import React from 'react';
import ReactDOM from 'react-dom';
import { ConfigProvider, Dialog, DatePicker, Button } from '@alifd/next';

class Demo extends React.Component {
  state = { visible: true };

  render() {
    return (
      <ConfigProvider popupContainer={node => node.parentNode}>
        <Dialog
          visible={this.state.visible}
          title="Welcome to Alibaba.com"
          onClose={() => this.setState({ visible: false })}
          footer={false}
        >
          <div style={{ margin: 20 }}>
            Start your business here by searching a popular product
            <DatePicker style={{ marginLeft: 20 }} placeholder="请选择日期" />
          </div>
          <div style={{ marginTop: 40, textAlign: 'right' }}>
            <Button type="primary" style={{ marginRight: 8 }}>确认</Button>
            <Button>取消</Button>
          </div>
        </Dialog>
      </ConfigProvider>
    );
  }
}

ReactDOM.render(<Demo />, mountNode);
